import {createRoot} from 'react-dom/client';
import type {MemoryApi} from '../../src/api';
import {App} from '../../src/App';
import {parseLocalChatSnapshot,type LifeCard,type LifeSettings,type GoogleAssistantOperation,type GoogleAssistantItem} from '@yui/domain';
import type {LifeServicesApi} from '../../src/life-services';
import type {GoogleCalendarTasksApi} from '../../src/google-calendar-tasks';
import {EMPTY_LOCAL_CHAT} from '../../src/local-state';
import '../../src/styles.css';
const now=()=>new Date().toISOString();
const profile={displayName:'確認用',addressingStyle:'san' as const,updatedAt:now()};
const read=<T,>(key:string,fallback:T):T=>JSON.parse(localStorage.getItem(key)??'null')??fallback;
const write=(key:string,value:unknown)=>localStorage.setItem(key,JSON.stringify(value));
const home={label:'架空市',query:'架空市',latitude:35,longitude:139,timezone:'Asia/Tokyo',precision:'locality' as const};
const initial:LifeSettings={revision:0,home:null,calendar:{id:'fixture-calendar',title:'仕事'},tasks:{id:'fixture-tasks',title:'やること'}};
const item:GoogleAssistantItem={service:'calendar',sourceId:'fixture-calendar',id:'fixture-item',version:'v1',title:'架空の打合せ',start:'2026-09-06T06:00:00Z',end:'2026-09-06T07:00:00Z'};
const list=()=>({service:'calendar' as const,sourceId:item.sourceId,items:[item],fetchedAt:now(),timeMin:'2026-09-06T00:00:00Z',timeMax:'2026-09-07T00:00:00Z'});
const getOp=(id:string):GoogleAssistantOperation=>{const value=read<GoogleAssistantOperation|null>(`fixture-op:${id}`,null);if(!value)throw new Error('missing fixture operation');return value;};
const api:LifeServicesApi={getSettings:async()=>read('fixture-settings',initial),saveSettings:async settings=>{const previous=read('fixture-settings',initial);if(previous.revision!==settings.revision)throw new Error('conflict');const next={...settings,revision:settings.revision+1};write('fixture-settings',next);return next;},locations:async()=>({candidates:[home],attribution:'架空データ'}),forecast:async()=>({home,days:[{date:'2026-09-06',temperatureMin:21,temperatureMax:28,precipitationProbability:60,weatherCode:3}],fetchedAt:now(),attribution:'架空の予報・実天気ではありません'}),list:async()=>list(),prepare:async request=>{const operation:GoogleAssistantOperation={operationId:'fixture-operation',signature:'fixture-signature',keyVersion:'v1',expiresAt:new Date(Date.now()+300000).toISOString(),state:'prepared',request,before:item};write(`fixture-op:${operation.operationId}`,operation);return operation;},confirm:async(id,signature)=>{const op=getOp(id);if(signature!==op.signature)throw new Error('signature');const next={...op,state:'succeeded' as const,result:{...item,...op.request.changes,version:'v2'} as GoogleAssistantItem};write(`fixture-op:${id}`,next);write('fixture-confirms',read('fixture-confirms',0)+1);return next;},cancel:async id=>{const next={...getOp(id),state:'cancelled' as const};write(`fixture-op:${id}`,next);return next;},operation:async id=>getOp(id),beginConnection:async()=>{throw new Error('このfixtureでは外部同意を行いません');}};
const google:GoogleCalendarTasksApi={getSettings:async()=>({calendar:{service:'calendar',state:'connected',homeVisible:false},tasks:{service:'tasks',state:'connected',homeVisible:false}}),sources:async service=>({service,checkedAt:now(),items:[{id:`fixture-${service}`,title:service==='calendar'?'仕事':'やること'}]}),beginConnection:async()=>{throw new Error('fixture');},setHomeVisible:async service=>({service,state:'connected',homeVisible:false}),stopService:async()=>{},checkCount:async()=>{},preview:async()=>{throw new Error('not used');}};
const memoryApi:MemoryApi={list:async()=>[],update:async()=>{throw new Error('fixture unused');},keep:async()=>{throw new Error('fixture unused');},forget:async()=>{},listTombstones:async()=>[],releaseTombstone:async()=>{},getSettings:async()=>({memoryEnabled:false,updatedAt:null}),updateSettings:async()=>({memoryEnabled:false,updatedAt:null})};
createRoot(document.getElementById('root')!).render(<App memoryApi={memoryApi} integratedUiEnabled lifeServicesApi={api} googleCalendarTasksApi={google} splashDurationMs={0} automaticMemoryEnabled={false} now={now} nextId={()=>crypto.randomUUID()} profileApi={{get:async()=>profile,save:async()=>profile}} chatStore={{load:async()=>parseLocalChatSnapshot(read('fixture-chat',null))??{...EMPTY_LOCAL_CHAT,lastOpeningAt:now()},save:async snapshot=>write('fixture-chat',snapshot)}} chatApi={{respond:async request=>{const text=request.timeline.filter(v=>v.type==='message'&&v.role==='user').at(-1);let lifeCard:LifeCard={kind:'google-items',sourceTitle:'仕事',result:list()};if(text?.type==='message'&&text.text.includes('天気'))lifeCard={kind:'weather',forecast:await api.forecast(1)};else if(text?.type==='message'&&text.text.includes('道'))lifeCard={kind:'maps',origin:home.label,destination:'東京駅',travelMode:'transit'};const replyGroupId=`${request.clientMessageId}:assistant`;return {replyGroupId,bubbles:[{id:`${replyGroupId}:0`,sequence:0,text:'確認用の結果を表示するね',createdAt:now(),flow:'external_context'}],lifeCard};}}}/>);
